255	\end{lemma}
256	\begin{proof}
257		\uses{lem:qld-4-7, lem:qld-constructing-the-paulis-helper, def:expanded-point-measurement, def:tilde-m-measurement, def:tau-dot-product-projector, lem:qld-decoder-evaluation, lem:qld-decoder-linearity, def:indicator-vector, lem:qld-win-implications, lem:qld-comm-cons, fact:add-a-proj, fact:agreement, fact:triangle, fact:data-processing, def:bracket, lem:povm-to-obs, lem:schwartz-zippel-total-degree}
258		% Support restriction added: the source (line 1492 of
259		% 14_analysis_of_the_pauli_basis_test.tex) rewrites Dec(g).ind_m(u) as
260		% g(u) for every outcome g; see Remark rem:qld-decoding-identity.
261		We first bound the mass that the marginal measurements $\{\hat{S}^W_g\}$ place on polynomials that are not encodings. On average over uniformly random $u \in \F_q^m$, the point-consistency relation \eqref{eq:qld-s-point-con-bob} of Lemma~\ref{lem:qld-4-7} gives $(\hat{S}^W_{[g(u)=a]})_{\mathrm{B}\mathrm{B}'} \approx_{\delta_G} (\hat{M}^{(\mathrm{Point},W),u}_a)_{\mathrm{A}\mathrm{B}''}$ (Lemma~\ref{fact:agreement}); the consistency and Pauli-basis-consistency checks of Lemma~\ref{lem:qld-win-implications} give, again on average over uniform $u$ and combining through Lemma~\ref{fact:data-processing}, Lemma~\ref{fact:agreement}, and Lemma~\ref{fact:triangle}, that $(M^{(\mathrm{Point},W),u}_{a'})_{\mathrm{A}} \approx_{O(\eps)} (M^{(\mathrm{Pauli},W)}_{[g_h(u)=a']})_{\mathrm{A}}$; and replacing the point factor of the convolution form of $\hat{M}^{(\mathrm{Point},W),u}_a$ (Definition~\ref{def:expanded-point-measurement}) accordingly costs the same error, because the projectors $\tau^W_{a''}(\mathrm{ind}_m(u))$ of \eqref{eq:def-tauwu} are mutually orthogonal (Lemma~\ref{fact:add-a-proj}). Writing
262		\[
263			K^u_a = \sum_{a' + a'' = a} \bigl(M^{(\mathrm{Pauli},W)}_{[g_h(u)=a']}\bigr)_{\mathrm{A}} \ot \bigl(\tau^W_{a''}(\mathrm{ind}_m(u))\bigr)_{\mathrm{B}''}\;,
264		\]
265		a projective measurement, Lemma~\ref{fact:triangle} and Lemma~\ref{fact:agreement} therefore give
266		\[
267			\E_{u \in \F_q^m} \sum_a \bra{\hat\psi} (\hat{S}^W_{[g(u)=a]})_{\mathrm{B}\mathrm{B}'} \ot (K^u_a)_{\mathrm{A}\mathrm{B}''} \ket{\hat\psi} \geq 1 - O(\delta_G + \eps)\;.
268		\]
269		Expanding $K^u_a$ over pairs $(h, h'')$ of Pauli outcomes, a term of the left-hand side with outcomes $(g, h, h'')$ is constrained by $g(u) = g_h(u) + g_{h''}(u) = g_{h + h''}(u)$, by the linearity of the encoding \eqref{eq:low-degree-encoding-definition}. If $g$ is not an encoding then $g \neq g_{h+h''}$, and both are polynomials of total degree at most $md$, so the constraint holds for at most an $md/q$ fraction of $u$ (Lemma~\ref{lem:schwartz-zippel-total-degree}). Since all terms are nonnegative and, for each $g$, the operators of the $(h,h'')$-sum add up to the identity, it follows that
270		\begin{equation}\label{eq:qld-nonencoding-mass}
271		\sum_{g \,\text{not an encoding}} \bra{\hat\psi} (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi} \,\leq\, O(\delta_G + \eps) + \frac{md}{q} \,\leq\, \delta_P\;,
272		\end{equation}
273		and symmetrically with the registers $\mathrm{A}\mathrm{A}'$ in place of $\mathrm{B}\mathrm{B}'$. (If $d = 0$, every element of $\mathrm{ideg}_{d,m}(\F_q)$ is constant, hence an encoding, and the left-hand side vanishes.)
274	
275		For the first item, in the case where $M^{(\mathrm{Point},W),u}_a$ acts on register $\mathrm{A}$ and $\tilde{M}^{W,\mathrm{ind}_m(u)}_a$ on $\mathrm{B}\mathrm{B}'\mathrm{B}''$, expanding \eqref{eq:tilde_M} and \eqref{eq:def-tauwu} and using the convolution form of the combined projectors $\hat{M}^{(\mathrm{Point},W),u}_a$ (Definition~\ref{def:expanded-point-measurement}) gives the exact identity
276		\[
277			\E_{u \in \F_q^m} \sum_a \bra{\hat\psi} M^{(\mathrm{Point},W),u}_a \ot \tilde{M}^{W,\mathrm{ind}_m(u)}_a \ket{\hat\psi}
278			= \E_{u \in \F_q^m} \sum_g \bra{\hat\psi} (\hat{M}^{(\mathrm{Point},W),u}_{\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)})_{\mathrm{A}\mathrm{B}''} \ot (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi}\;.
279		\]
280		For encodings $g$ the subscript $\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)$ equals $g(u)$; discarding the (nonnegative) terms with $g$ not an encoding and reinstating the corresponding terms with subscript $g(u)$, each of which is at most $\bra{\hat\psi} (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi}$, shows that the right-hand side is at least
281		\[
282			\E_{u \in \F_q^m} \sum_g \bra{\hat\psi} (\hat{M}^{(\mathrm{Point},W),u}_{g(u)})_{\mathrm{A}\mathrm{B}''} \ot (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi} - \delta_P
283			\geq 1 - \delta_P
284		\]
285		by \eqref{eq:qld-nonencoding-mass} and Lemma~\ref{lem:qld-4-7}, and the register-interchanged relation follows analogously. For the second item one first shows that, on average over uniformly random $\tilde{u} \in \F_q^M$,
286		\begin{equation}\label{eq:qld-pulling-cons}
287			\bigl( \tilde{M}^{W,\tilde{u}}_a \bigr)_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \approx_{\delta_P} \bigl( \tilde{M}^{W,\tilde{u}}_a \bigr)_{\mathrm{B}\mathrm{B}'\mathrm{B}''}\;:
288		\end{equation}
289		right-multiplying by the resolution $\sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point},W),u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \approx_{\delta_P} \Id$ of Lemma~\ref{lem:qld-constructing-the-paulis-helper} (with Lemma~\ref{fact:add-a-proj}) and expanding the products of $\tau^W$ projectors via \eqref{eq:def-tauwu} and $h \cdot \mathrm{ind}_m(u) = g_h(u)$ places $(\tilde{M}^{W,\tilde{u}}_a)_{\mathrm{A}\mathrm{A}'\mathrm{A}''}$ within $O(\delta_P)$ of a sum over pairs $(g,h)$ with $(\mathrm{Dec}(g)-h)\cdot\tilde{u} = a$. One then applies, in turn, the self-consistency of the points measurements (Lemma~\ref{lem:qld-win-implications}) at cost $\eps$; the exact identity $\ket{\hat\psi} = \sum_{h'} (\tau^W_{h'})_{\mathrm{B}'} \ot (\tau^W_{h'})_{\mathrm{B}''} \ket{\hat\psi}$ of the EPR registers; Lemma~\ref{lem:qld-constructing-the-paulis-helper} twice more (once through a Cauchy--Schwarz detour of cost $O(\sqrt{\eps})$ using the self-consistency of the $\hat{M}^{(\mathrm{Point},W),u}_a$, Lemma~\ref{lem:qld-comm-cons}); and finally a Schwartz--Zippel step (Lemma~\ref{lem:schwartz-zippel-total-degree}, for polynomials of total degree at most $md$) which replaces the event $(g'-g_{h'})(u) = (g-g_h)(u)$ by the polynomial identity $g'-g_{h'} = g-g_h$ at cost $md/q$. The resulting expression
290		\[
291			\sum_{\substack{g,h,g',h': \\ g' - g_{h'} = g - g_h \\ (\mathrm{Dec}(g)-h)\cdot \tilde{u} = a}}
292			\Bigl((\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\tau_h^W)_{\mathrm{A}''} \Bigr) \cdot \Bigl( (\hat{S}^W_{g'})_{\mathrm{B}\mathrm{B}'} \ot (\tau_{h'}^W)_{\mathrm{B}''} \Bigr)
293		\]
294		is symmetric under exchanging $(g,h)$ with $(g',h')$: since $\mathrm{Dec}$ is linear with $\mathrm{Dec}(g_{h}) = h$ for all $h \in \F_q^M$ (Remark~\ref{rem:qld-decoding-identity}), the constraint $g' - g_{h'} = g - g_h$ implies $\mathrm{Dec}(g) - h = \mathrm{Dec}(g') - h'$, so the two constraint sets coincide. The same derivation therefore bounds the distance of the displayed expression to $(\tilde{M}^{W,\tilde{u}}_a)_{\mathrm{B}\mathrm{B}'\mathrm{B}''}$, and \eqref{eq:qld-pulling-cons} follows at the common scale $\delta_P$. Finally, since $\{\tilde{M}^{W,\tilde{u}}_a\}$ is projective, Item~2 of Lemma~\ref{fact:agreement}, data processing along the map $a \mapsto \tr(e_j a)$ (Lemma~\ref{fact:data-processing}), and Item~1 of Lemma~\ref{fact:agreement} yield $(\tilde{M}^{W,\tilde{u}}_{[\tr(e_j \cdot) = b]})_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \approx_{\delta_P} (\tilde{M}^{W,\tilde{u}}_{[\tr(e_j \cdot) = b]})_{\mathrm{B}\mathrm{B}'\mathrm{B}''}$ with answer summation over $b \in \F_2$, and Lemma~\ref{lem:povm-to-obs} converts this into the claimed self-consistency of the observables $\tilde{W}^j(\tilde{u})$.
295	\end{proof}
