 384	\begin{lemma}[Unitarity and conjugation action of the swap unitaries]\label{lem:v-swap-conjugation}
 385		\lean{MIPStarRE.QPBT.swapUnitary_mul_conjTranspose}
 386		\lean{MIPStarRE.QPBT.conjTranspose_mul_swapUnitary}
 387		\lean{MIPStarRE.QPBT.swapUnitary_conj_tildeObs}
